import { HUMAN_TYPING_RATIO, PASTED_RATIO } from "./constants";
import type { ProvenanceSummary, Verdict } from "./types";

interface ClassifiableStats {
  totalChars: number;
}

/**
 * Pure function: map stats + summary to a verdict.
 *
 * Rules (per MVP spec):
 *   - Empty session                       -> Unverified
 *   - typingRatio >= 0.85 && !largePaste  -> Mostly typed
 *   - pastedRatio > 0.6 || largePaste     -> Mostly pasted
 *   - otherwise                           -> Mixed
 */
export function classify(
  stats: ClassifiableStats,
  summary: ProvenanceSummary,
): Verdict {
  if (stats.totalChars === 0) return "Unverified";
  if (summary.typingRatio >= HUMAN_TYPING_RATIO && !summary.hasLargePaste) {
    return "Mostly typed";
  }
  if (summary.pastedRatio > PASTED_RATIO || summary.hasLargePaste) {
    return "Mostly pasted";
  }
  return "Mixed";
}
